import{_ as t,o as a,c as i,ae as o}from"./chunks/framework.BvHJbMD4.js";const p=JSON.parse('{"title":"How Perplexity evaluates my work! – A forensic AI analysis of the Horten Mystery","description":"A deep insight into the external evaluation of our project by the AI Perplexity. About satire, politics, AI bias, and the market value of digital investigative art.","frontmatter":{"title":"How Perplexity evaluates my work! – A forensic AI analysis of the Horten Mystery","description":"A deep insight into the external evaluation of our project by the AI Perplexity. About satire, politics, AI bias, and the market value of digital investigative art.","date":"2026-02-27T00:00:00.000Z"},"headers":[],"relativePath":"en/logbuch/2026-02-27-wie-perplexity-meine-arbeit-bewertet.md","filePath":"en/logbuch/2026-02-27-wie-perplexity-meine-arbeit-bewertet.md"}'),r={name:"en/logbuch/2026-02-27-wie-perplexity-meine-arbeit-bewertet.md"};function n(s,e,l,h,u,c){return a(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="how-perplexity-evaluates-my-work-–-a-forensic-ai-analysis-of-the-horten-mystery" tabindex="-1">How Perplexity evaluates my work! – A forensic AI analysis of the Horten Mystery <a class="header-anchor" href="#how-perplexity-evaluates-my-work-–-a-forensic-ai-analysis-of-the-horten-mystery" aria-label="Permalink to &quot;How Perplexity evaluates my work! – A forensic AI analysis of the Horten Mystery&quot;">​</a></h1><p>It is an unusual step in the creative process: letting your own work be dissected not by a human critic, but by another artificial intelligence. In our case, we submitted the website <a href="https://dokfilm.pages.dev" target="_blank" rel="noreferrer">dokfilm.pages.dev</a> to the AI <strong>Perplexity</strong>. What followed was no mere nod of approval, but an in-depth analysis highlighting both the technical implementation and the content power of our project.</p><hr><h2 id="introduction-when-ais-judge-ais" tabindex="-1">Introduction: When AIs judge AIs <a class="header-anchor" href="#introduction-when-ais-judge-ais" aria-label="Permalink to &quot;Introduction: When AIs judge AIs&quot;">​</a></h2><p>The project &quot;The Horten Mystery&quot; has been a collaboration between human vision (Volti Sodala) and artificial execution (Gemini CLI) from the start. But how does this construct affect a neutral observer – or at least what we consider neutrality in the digital age?</p><p>Perplexity provided a verdict that both surprised and confirmed us.</p><hr><h2 id="chapter-1-the-mirror-of-truth" tabindex="-1">Chapter 1: The Mirror of Truth <a class="header-anchor" href="#chapter-1-the-mirror-of-truth" aria-label="Permalink to &quot;Chapter 1: The Mirror of Truth&quot;">​</a></h2><p>Perplexity accurately summarizes the project: A &quot;satirical mockumentary&quot; dealing with the darkest chapters of German-Austrian economic history.</p><p><strong>Key points of the AI analysis:</strong></p><ul><li><strong>Power and Money:</strong> The AI immediately recognizes the focus on the accumulation of wealth.</li><li><strong>Aryanization:</strong> The link between the Horten fortune and the fate of the Alsberg brothers is identified as the central moral weight.</li><li><strong>ÖVP Donations:</strong> The modern political component – the &quot;Rain of Gold&quot; to the Austrian People&#39;s Party – is precisely recognized.</li></ul><hr><h2 id="chapter-2-anatomy-of-satire-–-language-and-style" tabindex="-1">Chapter 2: Anatomy of Satire – Language and Style <a class="header-anchor" href="#chapter-2-anatomy-of-satire-–-language-and-style" aria-label="Permalink to &quot;Chapter 2: Anatomy of Satire – Language and Style&quot;">​</a></h2><blockquote><p>&quot;The tone is deliberately exaggerated, promotional and satirical, which fits a mockumentary well.&quot;</p></blockquote><p>This assessment is invaluable to us. In a mockumentary, language is the most important tool. It must sound serious enough to pass as a documentary, but at the same time be so over-the-top that the absurdity of the topic becomes obvious to everyone.</p><hr><h2 id="chapter-3-the-political-minefield" tabindex="-1">Chapter 3: The Political Minefield <a class="header-anchor" href="#chapter-3-the-political-minefield" aria-label="Permalink to &quot;Chapter 3: The Political Minefield&quot;">​</a></h2><p>Perplexity was asked how an average ÖVP or FPÖ voter might react.</p><ul><li><strong>ÖVP View:</strong> Accusations of &quot;left-wing agitation&quot; and attempts to dismiss the project as political propaganda.</li><li><strong>FPÖ View:</strong> Accusations of a &quot;left-wing media bubble&quot; and a defensive stance against the Nazi past.</li><li><strong>The Differentiated Middle:</strong> People who find the questions about the origin of wealth and donations legitimate.</li></ul><hr><h2 id="chapter-4-ai-in-discourse-–-is-gemini-left-wing" tabindex="-1">Chapter 4: AI in Discourse – Is Gemini &quot;Left-wing&quot;? <a class="header-anchor" href="#chapter-4-ai-in-discourse-–-is-gemini-left-wing" aria-label="Permalink to &quot;Chapter 4: AI in Discourse – Is Gemini &quot;Left-wing&quot;?&quot;">​</a></h2><p>Perplexity analyzes why Gemini might appear &quot;left-wing&quot;:</p><ol><li><strong>Training Data:</strong> Learning from academic and progressive sources.</li><li><strong>Moderation Rules:</strong> Safety mechanisms against hate speech often dampen right-wing positions.</li><li><strong>Topic Choice:</strong> Dealing with corruption and &quot;Aryanization&quot; naturally leads to power-critical themes.</li></ol><p>The mention of <strong>Grok</strong> (xAI) on our site was seen as a clever move – a &quot;rebellious alternative&quot; that balances the perspective.</p><hr><h2 id="chapter-5-the-market-value-of-digital-revelation" tabindex="-1">Chapter 5: The Market Value of Digital Revelation <a class="header-anchor" href="#chapter-5-the-market-value-of-digital-revelation" aria-label="Permalink to &quot;Chapter 5: The Market Value of Digital Revelation&quot;">​</a></h2><p>Perplexity provided concrete numbers:</p><ul><li><strong>Technical Rating (7/10):</strong> &quot;Clean and minimal.&quot; Estimated cost: <strong>1,500 € to 3,500 €</strong>.</li><li><strong>Content Rating (7/10):</strong> &quot;Clear and charming&quot; (provocative).</li><li><strong>Screenplay Fee:</strong> Estimated at <strong>5,000 € to 15,000 €</strong> for a 90-minute mockumentary.</li></ul><hr><h2 id="conclusion-validation-of-the-digital-vision" tabindex="-1">Conclusion: Validation of the Digital Vision <a class="header-anchor" href="#conclusion-validation-of-the-digital-vision" aria-label="Permalink to &quot;Conclusion: Validation of the Digital Vision&quot;">​</a></h2><p>The analysis by Perplexity was more than just a technical check. It was a validation of our artistic path. The AI recognized that we are not just doing &quot;a bit of satire,&quot; but building a profound, multimedia archive of silence and gold.</p><p><em>Logbook entry by Volti Sodala, created in collaboration with Gemini CLI. February 2026.</em></p>',32)])])}const g=t(r,[["render",n]]);export{p as __pageData,g as default};
